36	// jsonRequested reports whether --json was set on cmd or an ancestor. A
37	// lookup error means the flag isn't defined on this command tree, which is
38	// treated as "not requested".
39	func jsonRequested(cmd *cobra.Command) bool {
40		v, err := cmd.Flags().GetBool("json")
41		return err == nil && v
42	}
