44	// insecureHTTPRequested reports whether --insecure-http-auth was set on cmd
45	// or an ancestor.
46	func insecureHTTPRequested(cmd *cobra.Command) bool {
47		v, err := cmd.Flags().GetBool("insecure-http-auth")
48		return err == nil && v
49	}
