51	// addForceFlag registers the standard confirmation bypass on a destructive
52	// control-plane command: --force/-f, with --yes/-y as an alias. Either skips
53	// the prompt. Read the combined value with forceRequested.
54	func addForceFlag(cmd *cobra.Command) {
55		cmd.Flags().BoolP("force", "f", false, "Skip the confirmation prompt")
56		cmd.Flags().BoolP("yes", "y", false, "Skip the confirmation prompt (alias for --force)")
57	}
