67	// runControlPlaneDelete is the shared body of the destructive `delete` verbs
68	// (org/project/repo). It resolves the target ref to a ULID, gates on a
69	// confirmation prompt (bypassed by --force/--yes), deletes, and reports the
70	// resolved identifier. noun names the resource ("org"); ref is the user's
71	// original argument, shown alongside the resolved ULID. resolve and del isolate
72	// the per-resource API calls.
73	func runControlPlaneDelete(
74		cmd *cobra.Command,
75		noun, ref string,
76		resolve func(context.Context, *coreapi.Client) (string, error),
77		del func(context.Context, *coreapi.Client, string) error,
78	) error {
79		force := forceRequested(cmd)
80		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
81			id, err := resolve(ctx, c)
82			if err != nil {
83				return err
84			}
85			label := noun + " " + resolvedRefLabel(ref, id)
86			proceed, err := confirmControlPlaneDeletion(ctx, cmd.OutOrStdout(), label, force, interactive.CanPromptInteractively())
87			if err != nil {
88				return err
89			}
90			if !proceed {
91				return nil
92			}
93			if err := del(ctx, c, id); err != nil {
94				// Idempotent delete: a resource that's already gone (a 404 from the
95				// delete call — e.g. a ULID passed straight through, or a concurrent
96				// delete) is the desired end state, not an error.
97				if isCoreNotFound(err) {
98					fmt.Fprintf(cmd.OutOrStdout(), "%s not found; nothing to delete\n", label)
99					return nil
100				}
101				return err
102			}
103			fmt.Fprintf(cmd.OutOrStdout(), "✓ Deleted %s\n", label)
104			return nil
105		})
106	}
107	
108	// confirmControlPlaneDeletion gates a destructive control-plane delete. With
109	// force it proceeds silently. Otherwise it requires an interactive terminal:
110	// with none it refuses (returns an error) rather than deleting unprompted; with
111	// one it shows a confirmation form. canPrompt is passed in (not queried) so the
112	// decision is unit-testable without a TTY. label is the human description of
113	// the target, e.g. `org acme (01J…)`.
114	func confirmControlPlaneDeletion(ctx context.Context, w io.Writer, label string, force, canPrompt bool) (bool, error) {
115		if force {
116			return true, nil
117		}
118		if !canPrompt {
119			return false, fmt.Errorf("refusing to delete %s without confirmation; pass --force", label)
120		}
121		// huh opens the TTY during form startup regardless of context state, so
122		// guard explicitly to honor an already-cancelled command context.
123		if ctx.Err() != nil {
124			return false, nil //nolint:nilerr // cancelled context is a clean skip, not an error
125		}
126		confirmed := false
127		form := NewAccessibleForm(
128			huh.NewGroup(huh.NewConfirm().Title(fmt.Sprintf("Delete %s?", label)).Value(&confirmed)),
129		)
130		if err := form.RunWithContext(ctx); err != nil {
131			// A user abort (Esc) or context cancel (Ctrl+C) is a clean cancel, not
132			// an error — mirror confirmTrailDeletion.
133			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
134				return false, nil
135			}
136			return false, fmt.Errorf("deletion prompt: %w", err)
137		}
138		if !confirmed {
139			fmt.Fprintln(w, "Deletion cancelled.")
140			return false, nil
141		}
142		return true, nil
143	}
