145	// runCoreList fetches a slice via fn and renders it as an aligned table
146	// (default) or the raw wire JSON (--json). empty is the full sentence printed
147	// to stdout in place of the table when there are no items (e.g. "No
148	// organizations found."). headers names the columns; row maps one item to its
149	// cells in the same order. The human view keeps the output actionable — only
150	// the columns a person acts on — while --json preserves the full model for
151	// scripting.
152	func runCoreList[T any](cmd *cobra.Command, empty string, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) error {
153		return runCore(cmd, renderCoreList(cmd, empty, headers, row, fn))
154	}
