163	// renderCoreList builds the run-function shared by runCoreList and
164	// runCoreListForCluster: fetch via fn, then render as a table (default), the
165	// empty sentence (no items), or raw JSON (--json). Kept separate from the
166	// client-selection so the two list variants differ only in which core they
167	// dial.
168	func renderCoreList[T any](cmd *cobra.Command, empty string, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) func(context.Context, *coreapi.Client) error {
169		return func(ctx context.Context, c *coreapi.Client) error {
170			items, err := fn(ctx, c)
171			if err != nil {
172				return err
173			}
174			if jsonRequested(cmd) {
175				if items == nil {
176					items = []T{} // a nil slice encodes as null; scripts expect []
177				}
178				return printJSON(cmd.OutOrStdout(), items)
179			}
180			if len(items) == 0 {
181				fmt.Fprintln(cmd.OutOrStdout(), empty)
182				return nil
183			}
184			return printTable(cmd.OutOrStdout(), headers, items, row)
185		}
186	}
