214	// runCoreObject fetches a single value via fn and renders it as a vertical
215	// field/value list (default) or raw JSON (--json), reusing the same column
216	// definition as the matching list view.
217	func runCoreObject[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) (*T, error)) error {
218		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
219			item, err := fn(ctx, c)
220			if err != nil {
221				return err
222			}
223			if jsonRequested(cmd) {
224				return printJSON(cmd.OutOrStdout(), item)
225			}
226			return printFields(cmd.OutOrStdout(), headers, row(*item))
227		})
228	}
