230	// tableStyles holds the foreground styles for the human table/field views,
231	// matching the activity/session palette: gray ("8") for headers and
232	// secondary cells, white ("7") for the primary (first-column) value. When
233	// color is disabled (non-TTY, NO_COLOR — e.g. piped output and tests) the
234	// styles are no-ops and output is plain.
235	type tableStyles struct {
236		enabled bool
237		header  lipgloss.Style
238		primary lipgloss.Style
239		cell    lipgloss.Style
240	}
241	
242	func newTableStyles(w io.Writer) tableStyles {
243		if !shouldUseColor(w) {
244			return tableStyles{}
245		}
246		return tableStyles{
247			enabled: true,
248			header:  lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)).Bold(true),
249			primary: lipgloss.NewStyle(), // default fg: inverts with terminal theme
250			cell:    lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)),
251		}
252	}
253	
254	// style applies s to text only when color is enabled; otherwise it returns
255	// text unchanged so padding math and plain output stay correct.
256	func (t tableStyles) style(s lipgloss.Style, text string) string {
257		if !t.enabled {
258			return text
259		}
260		return s.Render(text)
261	}
262	
263	// columnStyle picks the foreground for a data cell: the first column is the
264	// primary identifier (white), the rest are secondary (gray).
265	func (t tableStyles) columnStyle(col int) lipgloss.Style {
266		if col == 0 {
267			return t.primary
268		}
269		return t.cell
270	}
271	
272	// printTable writes headers plus one row per item, columns aligned on the
273	// plain-text widths so ANSI color codes don't throw off the layout (they're
274	// applied after padding). Callers handle the empty case.
275	func printTable[T any](w io.Writer, headers []string, items []T, row func(T) []string) error {
276		st := newTableStyles(w)
277		rows := make([][]string, len(items))
278		for i, it := range items {
279			rows[i] = row(it)
280		}
281		widths := columnWidths(headers, rows)
282	
283		var b strings.Builder
284		writeTableRow(&b, headers, widths, func(int) lipgloss.Style { return st.header }, st)
285		for _, r := range rows {
286			writeTableRow(&b, r, widths, st.columnStyle, st)
287		}
288		if _, err := io.WriteString(w, b.String()); err != nil {
289			return fmt.Errorf("render table: %w", err)
290		}
291		return nil
292	}
293	
294	// printFields writes a single record as aligned "FIELD  value" lines: the
295	// label in header gray, the value in the same primary/secondary color the
296	// list view would give that column.
297	func printFields(w io.Writer, headers, values []string) error {
298		st := newTableStyles(w)
299		labelWidth := 0
300		for _, h := range headers {
301			if n := lipgloss.Width(h); n > labelWidth {
302				labelWidth = n
303			}
304		}
305		var b strings.Builder
306		for i, h := range headers {
307			var v string
308			if i < len(values) {
309				v = values[i]
310			}
311			label := st.style(st.header, h+strings.Repeat(" ", labelWidth-lipgloss.Width(h)))
312			b.WriteString(label)
313			b.WriteString("  ")
314			b.WriteString(st.style(st.columnStyle(i), v))
315			b.WriteByte('\n')
316		}
317		if _, err := io.WriteString(w, b.String()); err != nil {
318			return fmt.Errorf("render fields: %w", err)
319		}
320		return nil
321	}
322	
323	// columnWidths returns the max plain-text width of each column across the
324	// headers and all rows.
325	func columnWidths(headers []string, rows [][]string) []int {
326		widths := make([]int, len(headers))
327		for i, h := range headers {
328			widths[i] = lipgloss.Width(h)
329		}
330		for _, r := range rows {
331			for i, c := range r {
332				if i < len(widths) && lipgloss.Width(c) > widths[i] {
333					widths[i] = lipgloss.Width(c)
334				}
335			}
336		}
337		return widths
338	}
339	
340	// writeTableRow pads each cell to its column width on the plain text, then
341	// styles it — so alignment is computed before any ANSI codes are added.
342	// The final column isn't padded, avoiding trailing whitespace.
343	func writeTableRow(b *strings.Builder, cells []string, widths []int, styleFor func(col int) lipgloss.Style, st tableStyles) {
344		for i, c := range cells {
345			last := i == len(cells)-1
346			padded := c
347			if !last && i < len(widths) {
348				padded = c + strings.Repeat(" ", widths[i]-lipgloss.Width(c))
349			}
350			b.WriteString(st.style(styleFor(i), padded))
351			if !last {
352				b.WriteString("  ")
353			}
354		}
355		b.WriteByte('\n')
356	}
