381	// activeCoreClient builds the control-plane client for active-context
382	// commands. A package-level seam (production wiring is coreapi.New) so
383	// command-level tests can point the whole command tree at an httptest server
384	// without standing up the auth/context/TLS stack.
385	var activeCoreClient = func(context.Context) (*coreapi.Client, error) { return coreapi.New() }
386	
387	// runCore is the shared base for every active-context control-plane command:
388	// it owns the preamble only — silence usage, build the client, map API
389	// errors — and leaves all rendering to fn. The delete/revoke verbs call it
390	// directly and render their own output; runCoreList, runCoreObject, and
391	// runCoreMutation build on it to add their table/JSON/confirmation
392	// rendering. The client dials the active context's core (coreapi.New); use
393	// runCoreForCluster for commands addressed at a specific cluster.
394	func runCore(cmd *cobra.Command, fn func(ctx context.Context, c *coreapi.Client) error) error {
395		return runCoreClient(cmd, activeCoreClient, fn)
396	}
397	
398	// runCoreForCluster is runCore for resource-provider commands addressed at a
399	// specific cluster (mirror create/remove, mirror collaborators list):
400	// it dials the core that fronts clusterHost — discovered from the cluster's
401	// /.well-known/entire-cluster.json, authenticating with the matching local
402	// context — instead of the active context. So the command works on a cluster in
403	// a federation other than the active login, instead of failing with "unknown
404	// cluster_host". See coreapi.NewForCluster.
405	func runCoreForCluster(cmd *cobra.Command, clusterHost string, fn func(ctx context.Context, c *coreapi.Client) error) error {
406		return runCoreClient(cmd, func(ctx context.Context) (*coreapi.Client, error) {
407			return coreapi.NewForCluster(ctx, clusterHost)
408		}, fn)
409	}
410	
411	// runCoreClient owns the control-plane preamble shared by the active-context
412	// (runCore) and cluster-addressed (runCoreForCluster) variants: silence usage,
413	// opt into plain-HTTP token exchange if requested, build the client via
414	// newClient, run fn, and map API errors. The only difference between the two
415	// variants is which core newClient dials.
416	func runCoreClient(cmd *cobra.Command, newClient func(context.Context) (*coreapi.Client, error), fn func(ctx context.Context, c *coreapi.Client) error) error {
417		cmd.SilenceUsage = true
418		// Opt into plain-HTTP token exchange before the client (and its lazily
419		// built token manager) is constructed — the manager freezes the
420		// setting on first use.
421		if insecureHTTPRequested(cmd) {
422			auth.EnableInsecureHTTP()
423		}
424		client, err := newClient(cmd.Context())
425		if err != nil {
426			return fmt.Errorf("connect to Entire control plane: %w", err)
427		}
428		if err := fn(cmd.Context(), client); err != nil {
429			return renderCoreError(err)
430		}
431		return nil
432	}
