434	// markRequired marks one or more flags required, panicking if a name
435	// doesn't exist — that can only happen from a typo at wiring time, never
436	// at runtime, so a panic surfaces the bug immediately rather than letting
437	// a "required" flag silently not be enforced.
438	func markRequired(cmd *cobra.Command, names ...string) {
439		for _, name := range names {
440			if err := cmd.MarkFlagRequired(name); err != nil {
441				panic(fmt.Sprintf("mark flag %q required: %v", name, err))
442			}
443		}
444	}
