446	// renderCoreError converts a Core API error into the server's
447	// problem-detail message (so users see "organization name already taken"
448	// rather than ogen's decode-wrapped string), falling back to the raw error
449	// for transport/local failures. It returns a plain error, not a
450	// SilentError: main.go prints plain errors, and runCore has already set
451	// SilenceUsage, so the message reaches the user without a usage dump. (A
452	// SilentError here would be swallowed — main.go skips printing those —
453	// leaving e.g. a 409 conflict with no output.)
454	func renderCoreError(err error) error {
455		if err == nil {
456			return nil
457		}
458		if msg := coreapi.APIError(err); msg != "" {
459			return errors.New(msg)
460		}
461		return err
462	}
463	
464	// printJSON writes v as indented JSON to w — the --json view for list/get
465	// and mutations.
466	func printJSON(w io.Writer, v any) error {
467		enc := json.NewEncoder(w)
468		enc.SetIndent("", "  ")
469		if err := enc.Encode(v); err != nil {
470			return fmt.Errorf("encode output: %w", err)
471		}
472		return nil
473	}
