// rowFilter is one parsed --filter clause: term is a case-insensitive substring,
// and col is the column index it is scoped to (-1 = match any column). The index
// is resolved once at parse time so matching never re-does the header lookup.
type rowFilter struct {
	col  int
	term string
}

// filterRows keeps items whose rendered cells satisfy EVERY clause (AND),
// matching on exactly what the table shows so the filter tracks the visible
// columns. Each clause is a case-insensitive substring: a bare "term" matches
// any column; "col=term" scopes the match to the column named col (a header,
// case-insensitive). Empty clauses are ignored; no effective clauses returns
// items unchanged. An unknown column name is an error that names the valid
// columns so a typo fails loudly instead of silently matching nothing. The
// result reuses no backing array (items[:0:0]) so it stays non-nil even when
// empty — callers encode it as JSON, where [] and null differ.
func filterRows[T any](items []T, headers []string, row func(T) []string, clauses []string) ([]T, error) {
	filters := make([]rowFilter, 0, len(clauses))
	for _, clause := range clauses {
		if clause == "" {
			continue
		}
		col, term := -1, strings.ToLower(clause)
		if k, v, ok := strings.Cut(clause, "="); ok {
			name := strings.ToLower(strings.TrimSpace(k))
			if col = headerIndex(headers, name); col < 0 {
				return nil, fmt.Errorf("unknown filter column %q; valid columns: %s", name, strings.ToLower(strings.Join(headers, ", ")))
			}
			term = strings.ToLower(v)
		}
		filters = append(filters, rowFilter{col: col, term: term})
	}
	if len(filters) == 0 {
		return items, nil
	}
	out := items[:0:0]
	for _, it := range items {
		if matchesAll(row(it), filters) {
			out = append(out, it)
		}
	}
	return out, nil
}

// matchesAll reports whether cells satisfy every filter (AND).
func matchesAll(cells []string, filters []rowFilter) bool {
	for _, f := range filters {
		if !rowMatches(cells, f.col, f.term) {
			return false
		}
	}
	return true
}

// rowMatches reports whether cells contain term (case-insensitive). idx < 0
// matches any cell; otherwise only the cell at idx.
func rowMatches(cells []string, idx int, term string) bool {
	if idx >= 0 {
		return strings.Contains(strings.ToLower(cellAt(cells, idx)), term)
	}
	for _, c := range cells {
		if strings.Contains(strings.ToLower(c), term) {
			return true
		}
	}
	return false
}

