// TestRepoMirrorList_FilterSort pins the client-side --filter and --sort applied
// to `repo mirror list` before rendering, so they shape both the table and
// --json output and work under --show-available.
//
// Not parallel: swaps the package-level activeCoreClient seam.
func TestRepoMirrorList_FilterSort(t *testing.T) {
	mirrors := []coreapi.Mirror{
		{Owner: "acme", Repo: "web", ClusterHost: "aws-us-east-2.entire.io"},
		{Owner: "acme", Repo: "cli", ClusterHost: "aws-us-east-2.entire.io"},
		{Owner: "other", Repo: "api", ClusterHost: "aws-us-east-2.entire.io"},
	}

	t.Run("--filter narrows the table to matching rows", func(t *testing.T) {
		serveMirrorList(t, mirrors, nil)
		stdout, _ := runMirrorList(t, "--filter", "cli")
		require.Contains(t, stdout, "acme/cli")
		require.NotContains(t, stdout, "acme/web")
		require.NotContains(t, stdout, "other/api")
	})

	t.Run("scoped --filter repo=cli matches only the REPO column", func(t *testing.T) {
		serveMirrorList(t, mirrors, nil)
		stdout, _ := runMirrorList(t, "--filter", "repo=cli")
		require.Contains(t, stdout, "acme/cli")
		require.NotContains(t, stdout, "other/api")
	})

	t.Run("repeatable --filter clauses AND together", func(t *testing.T) {
		serveMirrorList(t, mirrors, nil)
		stdout, _ := runMirrorList(t, "--filter", "repo=acme", "--filter", "repo=web")
		require.Contains(t, stdout, "acme/web")
		require.NotContains(t, stdout, "acme/cli")
		require.NotContains(t, stdout, "other/api")
	})

	t.Run("default output is repo-name sorted", func(t *testing.T) {
		serveMirrorList(t, mirrors, nil)
		stdout, _ := runMirrorList(t)
		// acme/cli < acme/web < other/api
		require.Less(t, strings.Index(stdout, "acme/cli"), strings.Index(stdout, "acme/web"))
		require.Less(t, strings.Index(stdout, "acme/web"), strings.Index(stdout, "other/api"))
	})

	t.Run("--sort -repo reverses the order", func(t *testing.T) {
		serveMirrorList(t, mirrors, nil)
		stdout, _ := runMirrorList(t, "--sort", "-repo")
		require.Less(t, strings.Index(stdout, "other/api"), strings.Index(stdout, "acme/web"))
		require.Less(t, strings.Index(stdout, "acme/web"), strings.Index(stdout, "acme/cli"))
	})

	t.Run("--filter applies to --json and keeps [] not null", func(t *testing.T) {
		serveMirrorList(t, mirrors, nil)
		stdout, _ := runMirrorList(t, "--filter", "cli", "--json")
		require.Contains(t, stdout, `"repo": "cli"`)
		require.NotContains(t, stdout, `"repo": "web"`)

		serveMirrorList(t, mirrors, nil)
		stdout, _ = runMirrorList(t, "--filter", "zzz", "--json")
		require.Contains(t, stdout, "[]")
		require.NotContains(t, stdout, "null")
	})

	t.Run("unknown --filter column errors naming valid columns", func(t *testing.T) {
		serveMirrorList(t, mirrors, nil)
		err := runMirrorListErr(t, "--filter", "nope=x")
		require.Error(t, err)
		require.Contains(t, err.Error(), "unknown filter column")
		require.Contains(t, err.Error(), "repo")
	})

	t.Run("unknown --sort column errors naming valid columns", func(t *testing.T) {
		serveMirrorList(t, mirrors, nil)
		err := runMirrorListErr(t, "--sort", "nope")
		require.Error(t, err)
		require.Contains(t, err.Error(), "unknown sort column")
	})

	t.Run("cluster is filterable via the clone URL (no CLUSTER column)", func(t *testing.T) {
		dupes := []coreapi.Mirror{
			{Owner: "acme", Repo: "web", ClusterHost: "eu-west-1.entire.io"},
			{Owner: "acme", Repo: "web", ClusterHost: "aws-us-east-2.entire.io"},
		}
		serveMirrorList(t, dupes, nil)
		stdout, _ := runMirrorList(t, "--filter", "aws")
		// The cluster host lives in the clone URL, so a bare filter matches it.
		require.Contains(t, stdout, "entire://aws-us-east-2.entire.io/gh/acme/web")
		require.NotContains(t, stdout, "eu-west-1.entire.io")
		// No dedicated CLUSTER column.
		require.NotContains(t, stdout, "CLUSTER")
	})

	t.Run("default order breaks duplicate-repo ties by cluster ascending", func(t *testing.T) {
		// Same repo on two clusters, delivered eu-first; the default sort must
		// deterministically place aws before eu.
		dupes := []coreapi.Mirror{
			{Owner: "acme", Repo: "web", ClusterHost: "eu-west-1.entire.io"},
			{Owner: "acme", Repo: "web", ClusterHost: "aws-us-east-2.entire.io"},
		}
		serveMirrorList(t, dupes, nil)
		stdout, _ := runMirrorList(t)
		require.Less(t,
			strings.Index(stdout, "entire://aws-us-east-2.entire.io/gh/acme/web"),
			strings.Index(stdout, "entire://eu-west-1.entire.io/gh/acme/web"),
		)
	})

	t.Run("--filter/--sort apply under --show-available", func(t *testing.T) {
		serveMirrorList(t, nil, []coreapi.AvailableMirror{
			{Owner: "acme", Repo: "web", Access: "write", Status: "available"},
			{Owner: "acme", Repo: "cli", Access: "read", Status: "available"},
		})
		stdout, _ := runMirrorList(t, "--show-available", "--filter", "repo=cli", "--sort", "access")
		require.Contains(t, stdout, "acme/cli")
		require.NotContains(t, stdout, "acme/web")
	})
}

