package cli

import (
	"fmt"
	"strings"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"
	"github.com/atotto/clipboard"

	"github.com/entireio/cli/cmd/entire/cli/palette"
	"github.com/entireio/cli/internal/coreapi"
)

// cloneCommandForMirror is the shell command that clones a mirror — what a
// click/Enter copies to the clipboard. The clone URL is the exact form
// `entire repo clone` accepts (see repo_clone.go), so the copied line is
// runnable as-is.
func cloneCommandForMirror(m coreapi.Mirror) string {
	return "entire repo clone " + mirrorCloneURL(m.ClusterHost, m.Owner, m.Repo)
}

// mirrorTUIHeaderLines is the number of lines above the first mirror row in the
// TUI (the column header). Mouse-click Y coordinates are mapped to a row by
// subtracting this and adding the scroll offset.
const mirrorTUIHeaderLines = 1

// mirrorCopyModel is the interactive `repo mirror list` view: a scrollable
// table where clicking a row (or selecting it with the keyboard and pressing
// Enter) copies that mirror's `entire repo clone …` command to the clipboard.
// It's only used on an interactive TTY; piped/--json/accessible output uses the
// plain table (see newRepoMirrorListCmd), so this never gates non-interactive
// use.
type mirrorCopyModel struct {
	mirrors []coreapi.Mirror
	rows    [][]string // rendered cells, one per mirror (mirrorRow)
	widths  []int      // column widths across header + rows
	cursor  int        // selected row index
	offset  int        // index of the first visible row (scroll)
	width   int
	height  int
	status  string // transient feedback ("Copied …" / "copy failed …")
	// copyFn writes to the clipboard; a seam so tests don't touch the real one.
	copyFn func(string) error
}

func newMirrorCopyModel(mirrors []coreapi.Mirror) mirrorCopyModel {
	rows := make([][]string, len(mirrors))
	for i, m := range mirrors {
		rows[i] = mirrorRow(m)
	}
	return mirrorCopyModel{
		mirrors: mirrors,
		rows:    rows,
		widths:  columnWidths(mirrorColumns, rows),
		copyFn:  clipboard.WriteAll,
	}
}

func (m mirrorCopyModel) Init() tea.Cmd { return nil }

// visibleRows is how many mirror rows fit on screen, leaving room for the
// column header and the two-line footer (help + status). At least one.
func (m mirrorCopyModel) visibleRows() int {
	return max(1, m.height-mirrorTUIHeaderLines-2)
}

func (m mirrorCopyModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width, m.height = msg.Width, msg.Height
		m = m.clampScroll()
		return m, nil

	case tea.KeyPressMsg:
		switch msg.String() {
		case "q", "esc", "ctrl+c":
			return m, tea.Quit
		case "up", "k":
			m = m.moveCursor(-1)
		case "down", "j":
			m = m.moveCursor(1)
		case "enter", " ", "c":
			m = m.copySelected()
		}
		return m, nil

	case tea.MouseClickMsg:
		if msg.Button != tea.MouseLeft {
			return m, nil
		}
		// Map the click's Y to a row: rows start after the header and are offset
		// by the current scroll position.
		row := m.offset + msg.Y - mirrorTUIHeaderLines
		if row >= 0 && row < len(m.mirrors) {
			m.cursor = row
			m = m.clampScroll()
			m = m.copySelected()
		}
		return m, nil
	}
	return m, nil
}

func (m mirrorCopyModel) moveCursor(delta int) mirrorCopyModel {
	m.cursor = min(max(m.cursor+delta, 0), len(m.mirrors)-1)
	return m.clampScroll()
}

// clampScroll keeps offset such that the cursor is within the visible window.
func (m mirrorCopyModel) clampScroll() mirrorCopyModel {
	vis := m.visibleRows()
	if m.cursor < m.offset {
		m.offset = m.cursor
	} else if m.cursor >= m.offset+vis {
		m.offset = m.cursor - vis + 1
	}
	if m.offset < 0 {
		m.offset = 0
	}
	return m
}

func (m mirrorCopyModel) copySelected() mirrorCopyModel {
	if len(m.mirrors) == 0 {
		return m
	}
	cmd := cloneCommandForMirror(m.mirrors[m.cursor])
	if err := m.copyFn(cmd); err != nil {
		m.status = "copy failed: " + err.Error()
		return m
	}
	m.status = "✓ Copied: " + cmd
	return m
}

func (m mirrorCopyModel) View() tea.View {
	v := tea.View{AltScreen: true, MouseMode: tea.MouseModeCellMotion}
	if m.width == 0 || m.height == 0 {
		return v
	}
	color := m.width > 0 // AltScreen is a real terminal; color is safe
	st := mirrorTUIStyles(color)

	var b strings.Builder
	b.WriteString(renderMirrorRow(mirrorColumns, m.widths, st.header, st.header))
	b.WriteByte('\n')

	vis := m.visibleRows()
	end := min(m.offset+vis, len(m.rows))
	for i := m.offset; i < end; i++ {
		cellStyle, selStyle := st.cell, st.cell
		if i == m.cursor {
			cellStyle, selStyle = st.selected, st.selected
		}
		b.WriteString(renderMirrorRow(m.rows[i], m.widths, cellStyle, selStyle))
		b.WriteByte('\n')
	}

	// Pad so the footer sits at the bottom regardless of row count.
	used := mirrorTUIHeaderLines + (end - m.offset)
	for i := used; i < m.height-2; i++ {
		b.WriteByte('\n')
	}
	b.WriteString(st.help.Render("↑/↓ move • enter/click copy clone command • q quit"))
	b.WriteByte('\n')
	b.WriteString(st.status.Render(m.status))

	v.SetContent(b.String())
	return v
}

// renderMirrorRow formats one row's cells padded to widths. The first column
// uses primary, the rest use secondary; a selected row passes the same style
// for both so the whole line highlights.
func renderMirrorRow(cells []string, widths []int, primary, secondary lipgloss.Style) string {
	var b strings.Builder
	for i, c := range cells {
		last := i == len(cells)-1
		padded := c
		if !last && i < len(widths) {
			padded = c + strings.Repeat(" ", widths[i]-lipgloss.Width(c))
		}
		style := secondary
		if i == 0 {
			style = primary
		}
		b.WriteString(style.Render(padded))
		if !last {
			b.WriteString("  ")
		}
	}
	return b.String()
}

type mirrorTUIStyleSet struct {
	header   lipgloss.Style
	cell     lipgloss.Style
	selected lipgloss.Style
	help     lipgloss.Style
	status   lipgloss.Style
}

func mirrorTUIStyles(color bool) mirrorTUIStyleSet {
	if !color {
		plain := lipgloss.NewStyle()
		return mirrorTUIStyleSet{plain, plain, plain, plain, plain}
	}
	return mirrorTUIStyleSet{
		header:   lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)).Bold(true),
		cell:     lipgloss.NewStyle(),
		selected: lipgloss.NewStyle().Reverse(true),
		help:     lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)),
		status:   lipgloss.NewStyle().Bold(true),
	}
}

// runMirrorCloneTUI launches the interactive click-to-copy list. Empty results
// fall back to the plain sentence so the interactive path matches the table.
func runMirrorCloneTUI(cmd *cobra.Command, mirrors []coreapi.Mirror) error {
	if len(mirrors) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "No mirrors found.")
		return nil
	}
	if _, err := tea.NewProgram(newMirrorCopyModel(mirrors)).Run(); err != nil {
		return fmt.Errorf("mirror list TUI: %w", err)
	}
	return nil
}

