package cli

import (
	"errors"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/stretchr/testify/require"

	"github.com/entireio/cli/internal/coreapi"
)

// TestMirrorCopyModel exercises the interactive click-to-copy list via the
// injected copyFn seam, so it never touches the real system clipboard and needs
// no TTY. The command-level plain-table path is covered by
// TestRepoMirrorList_FilterSort (non-TTY output stays a table).
func TestMirrorCopyModel(t *testing.T) {
	t.Parallel()
	mirrors := []coreapi.Mirror{
		{Owner: "acme", Repo: "web", ClusterHost: "aws-us-east-2.entire.io"},
		{Owner: "acme", Repo: "cli", ClusterHost: "eu-west-1.entire.io"},
	}

	t.Run("cloneCommandForMirror is a runnable clone command", func(t *testing.T) {
		t.Parallel()
		require.Equal(t,
			"entire repo clone entire://aws-us-east-2.entire.io/gh/acme/web",
			cloneCommandForMirror(mirrors[0]),
		)
	})

	t.Run("copySelected copies the selected clone command", func(t *testing.T) {
		t.Parallel()
		var got string
		m := newMirrorCopyModel(mirrors)
		m.copyFn = func(s string) error { got = s; return nil }
		m = m.copySelected()
		require.Equal(t, cloneCommandForMirror(mirrors[0]), got)
		require.Contains(t, m.status, "Copied")
	})

	t.Run("copy failure surfaces in the status line", func(t *testing.T) {
		t.Parallel()
		m := newMirrorCopyModel(mirrors)
		m.copyFn = func(string) error { return errors.New("no clipboard") }
		m = m.copySelected()
		require.Contains(t, m.status, "copy failed")
	})

	t.Run("left click selects and copies the clicked row", func(t *testing.T) {
		t.Parallel()
		var got string
		m := newMirrorCopyModel(mirrors)
		m.copyFn = func(s string) error { got = s; return nil }
		sized, _ := m.Update(tea.WindowSizeMsg{Width: 80, Height: 20})
		// Y=2: header is line 0, first row line 1, so line 2 is the second row.
		clicked, _ := sized.(mirrorCopyModel).Update(tea.MouseClickMsg{Y: 2, Button: tea.MouseLeft})
		model := clicked.(mirrorCopyModel)
		require.Equal(t, 1, model.cursor)
		require.Equal(t, cloneCommandForMirror(mirrors[1]), got)
	})

	t.Run("click on the header line copies nothing", func(t *testing.T) {
		t.Parallel()
		called := false
		m := newMirrorCopyModel(mirrors)
		m.copyFn = func(string) error { called = true; return nil }
		sized, _ := m.Update(tea.WindowSizeMsg{Width: 80, Height: 20})
		sized.(mirrorCopyModel).Update(tea.MouseClickMsg{Y: 0, Button: tea.MouseLeft})
		require.False(t, called, "clicking the column header must not copy")
	})

	t.Run("moveCursor clamps at both ends", func(t *testing.T) {
		t.Parallel()
		m := newMirrorCopyModel(mirrors)
		m = m.moveCursor(-1)
		require.Equal(t, 0, m.cursor)
		m = m.moveCursor(5)
		require.Equal(t, len(mirrors)-1, m.cursor)
	})
}

